/*
 * The offline layer for Postgres Lab. Hand written on purpose: the app keeps no other build-time
 * dependency on a bundler plugin, and this file is served from `public/`, so it is never processed,
 * bundled or minified by Next. What it does is small enough to read here in full.
 *
 * Why there is no precache manifest. A generated list of hashed chunk URLs would have to be
 * regenerated by the build, which would mean a plugin; and it would not be needed anyway. Every URL
 * this worker caches is fetched by the app *because the reader asked for the thing that needs it*:
 * the 16 MB of PGlite WASM only arrives when the playground boots, and Monaco's worker only arrives
 * when the editor mounts. Cache-on-first-use therefore gets the same offline coverage for 0 extra
 * bytes. Two things are installed eagerly anyway, both because cache-on-first-use cannot reach them:
 * the offline document (fetched only when fetching has failed) and `/icon.svg` (fetched by a page the
 * worker does not yet control). See the install handler.
 *
 * The two rules that matter, in order of how bad breaking them would be:
 *  1. `/api/` is never intercepted, and neither is anything that is not a same-origin-shaped GET.
 *     `/api/db` runs SQL against a live server and `/api/ai` spends a rate-limited quota; a cached
 *     response to either would be a wrong answer served as a right one, and a stored mutation.
 *  2. Nothing here needs a build-time list, so nothing here can go stale against the next build.
 *     `/_next/static/**` is content-hashed and immutable by construction, so cache-first cannot
 *     serve a stale chunk: a new build means new URLs. HTML is the opposite, so HTML is
 *     network-first and falls back to the cache only when the network has actually failed.
 *
 * `VERSION` is the manual reset. Bump it when a response shape changes in a way the hash does not
 * cover (that is: HTML, the offline page, and the Monaco CDN URLs, which are versioned in their path
 * but not covered by Next's hashing). Old caches are dropped on activate, and the new worker takes
 * over on install so a returning reader is never pinned to the previous build.
 */

const VERSION = 'v1';
const STATIC = `pglab-static-${VERSION}`;
const MONACO = `pglab-monaco-${VERSION}`;
const PAGES = `pglab-pages-${VERSION}`;
const OFFLINE_DOC = '/offline';

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(STATIC)
      // The offline document is precached because no request can ever arrive for it to be cached by:
      // it is fetched only when fetching has already failed. The icon joins it for a different
      // reason: a page's first load happens before this worker controls that page, so the browser's
      // fetch of `/icon.svg` is one the worker never sees, and offline it fails (a favicon error on
      // every offline load, logged and cosmetic). Both are small, and neither has a hashed URL.
      .then((c) => Promise.all([c.add(OFFLINE_DOC), c.add('/icon.svg')]))
      // An unavailable server at install time must not fail the install; the offline page is a
      // nicety, the worker is not. Retry happens on the next navigation.
      .catch(() => undefined)
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((names) => Promise.all(names.filter((n) => n.startsWith('pglab-') && !n.endsWith(VERSION)).map((n) => caches.delete(n))))
      .then(() => self.clients.claim()),
  );
});

/**
 * The whole policy, as a pure function so it can be tested by importing this file with a stubbed
 * worker scope (`src/lib/pwa/offline.test.ts`) rather than by reasoning about it.
 *
 * `passthrough` means the worker does not respond at all and the browser does what it would have
 * done with no worker installed. That is the correct answer for anything that reaches the network on
 * the reader's behalf rather than fetching a file.
 */
function decide(request) {
  const url = new URL(request.url);
  if (request.method !== 'GET') return 'passthrough';
  if (url.pathname === '/api' || url.pathname.startsWith('/api/')) return 'passthrough';
  if (url.origin !== self.location.origin && url.hostname !== 'cdn.jsdelivr.net') return 'passthrough';
  if (request.mode === 'navigate') return url.pathname === OFFLINE_DOC ? 'cacheFirst' : 'networkFirst';
  if (url.origin === self.location.origin && url.pathname.startsWith('/_next/static/')) return 'cacheFirst';
  if (url.hostname === 'cdn.jsdelivr.net') return 'cacheFirst';
  // A cross-origin WASM or font would land here. Anything we cannot name is not cached.
  if (url.origin !== self.location.origin) return 'passthrough';
  // RSC payload fetches (`?_rsc=`) and favicon-style assets: same origin, not hashed. Cache them
  // only as a fallback, so a client navigation after a fresh build still gets the new tree.
  return url.search ? 'networkFirst' : 'cacheFirst';
}

const CACHE_FOR = { cacheFirst: STATIC, networkFirst: PAGES };

self.addEventListener('fetch', (event) => {
  const action = decide(event.request);
  if (action === 'passthrough') return;

  const isMonaco = new URL(event.request.url).hostname === 'cdn.jsdelivr.net';
  const cacheName = isMonaco ? MONACO : CACHE_FOR[action];

  event.respondWith(
    action === 'cacheFirst'
      ? caches.match(event.request, { cacheName }).then(
          (hit) =>
            hit ??
            fetch(event.request).then((res) => {
              if (cacheable(res, isMonaco)) cachePut(cacheName, event.request, res.clone());
              return res;
            }),
        )
      : networkFirst(event.request, cacheName),
  );
});

/**
 * Whether a response is worth a slot in a cache.
 *
 * `res.ok` covers everything from our own origin. It does not cover the editor: Monaco's AMD loader
 * pulls its chunks in with classic <script> tags, which the browser fetches in no-cors mode, and a
 * no-cors response reaches the worker as type 'opaque' with status 0, so a perfectly good 200
 * reports itself as not ok. Filtering on `res.ok` alone is what left the editor needing a network
 * while offline (production build: 12 CDN requests, 0 entries in the Monaco cache). Storing an
 * opaque response is allowed, measured rather than assumed, `put` of a no-cors jsdelivr response
 * succeeds. `res.clone()` either way, because `put` consumes the body and the page is holding the
 * only other copy.
 *
 * The allowance is for the one CDN this app depends on. Anywhere else, a status the worker cannot
 * read is reason enough not to keep the bytes.
 */
function cacheable(res, isMonaco) {
  if (res.ok && (res.type === 'basic' || res.type === 'cors')) return true;
  return isMonaco && res.type === 'opaque';
}

async function networkFirst(request, cacheName) {
  try {
    const res = await fetch(request);
    // HTML is same-origin and never Monaco, so the CDN allowance is deliberately not on offer here.
    if (cacheable(res, false)) cachePut(cacheName, request, res.clone());
    return res;
  } catch {
    const cached = await caches.match(request, { cacheName });
    if (cached) return cached;
    // A document the reader has never visited, with no network: the one page that can explain why.
    if (request.mode === 'navigate') {
      const offline = await caches.match(OFFLINE_DOC, { cacheName: STATIC });
      if (offline) return offline;
    }
    throw new Error(`pglab: offline, and nothing cached for ${request.url}`);
  }
}

function cachePut(cacheName, request, response) {
  caches.open(cacheName).then((c) => c.put(request, response)).catch(() => undefined);
}
